#!/usr/bin/env bash
# Pin the SSH host keys of the lab VMs for Ansible and the webhook pod.
#
# The keys are read through the QEMU guest agent (virsh qemu-agent-command),
# not over the network, so a host on the libvirt bridge cannot substitute its
# own key. Both inventories are covered: the kubeadm nodes (kubeadm.ini,
# generated by terraform) and the machines outside the cluster (infra.ini,
# whose libvirt VM names are given by vm_name=). The hypervisor's own keys
# are read from its local /etc/ssh (this script runs on the hypervisor) and
# pinned under HYPERVISOR_IP, the address the webhook pod uses for virsh and
# docker commands. The result is written to ansible/inventory/known_hosts,
# which the inventories use with StrictHostKeyChecking=yes and which is
# mounted into the webhook pod (see docs/runbooks/applications/secret-rotation.md).
#
# Run after the VMs have booted (qemu-guest-agent is installed by cloud-init):
#   ./scripts/kubeadm-known-hosts.sh
#   HYPERVISOR_IP=10.0.0.1 ./scripts/kubeadm-known-hosts.sh   # non-default bridge address
set -euo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")/.."
INVENTORIES="ansible/inventory/kubeadm.ini ansible/inventory/infra.ini"
KNOWN_HOSTS=ansible/inventory/known_hosts
KEY_TYPES="ed25519 ecdsa rsa"
HYPERVISOR_IP=${HYPERVISOR_IP:-192.168.122.1}

guest_exec() {
    # guest_exec <vm> <command...>: run a command in the guest and print its stdout
    local vm=$1; shift
    local args pid status
    args=$(printf '%s\n' "$@" | python3 -c 'import json,sys; print(json.dumps(sys.stdin.read().splitlines()))')
    pid=$(virsh qemu-agent-command "$vm" \
        "{\"execute\":\"guest-exec\",\"arguments\":{\"path\":\"/bin/sh\",\"arg\":$args,\"capture-output\":true}}" \
        | python3 -c 'import json,sys; print(json.load(sys.stdin)["return"]["pid"])')
    for _ in $(seq 1 20); do
        status=$(virsh qemu-agent-command "$vm" \
            "{\"execute\":\"guest-exec-status\",\"arguments\":{\"pid\":$pid}}")
        if python3 -c 'import json,sys; sys.exit(0 if json.load(sys.stdin)["return"]["exited"] else 1)' <<< "$status"; then
            python3 -c 'import json,sys,base64; r=json.load(sys.stdin)["return"]; print(base64.b64decode(r.get("out-data","")).decode().strip())' <<< "$status"
            return 0
        fi
        sleep 0.5
    done
    echo "Error: guest command on $vm did not finish." >&2
    return 1
}

if ! virsh list --name >/dev/null 2>&1; then
    echo "Error: cannot talk to libvirt." >&2
    exit 1
fi

tmp=$(mktemp)
trap 'rm -f "$tmp"' EXIT

# Host lines: "<name> ansible_host=<ip> [vm_name=<libvirt name>]"; the VM
# name defaults to the inventory name.
list_hosts() {
    local inv
    for inv in $INVENTORIES; do
        [ -f "$inv" ] || continue
        awk '/^[A-Za-z0-9][A-Za-z0-9.-]*[[:space:]]+ansible_host=/ {
            vm = $1; ip = ""
            for (i = 2; i <= NF; i++) {
                split($i, kv, "=")
                if (kv[1] == "ansible_host") ip = kv[2]
                if (kv[1] == "vm_name") vm = kv[2]
            }
            if (ip != "") print vm, ip
        }' "$inv"
    done
}

while read -r vm ip; do
    if [ "$(virsh domstate "$vm" 2>/dev/null)" != "running" ]; then
        echo "Error: $vm is not running; start the VMs first." >&2
        exit 1
    fi
    cat_cmd="cat"
    for keytype in $KEY_TYPES; do
        cat_cmd="$cat_cmd /etc/ssh/ssh_host_${keytype}_key.pub"
    done
    keys=$(guest_exec "$vm" -c "$cat_cmd 2>/dev/null")
    if [ -z "$keys" ]; then
        echo "Error: no host keys read from $vm." >&2
        exit 1
    fi
    while read -r keytype keydata _; do
        printf '%s %s %s\n' "$ip" "$keytype" "$keydata" >> "$tmp"
    done <<< "$keys"
    echo "pinned $vm ($ip)"
done < <(list_hosts)

# The hypervisor itself: local files, no network involved.
hv_keys=""
for keytype in $KEY_TYPES; do
    f=/etc/ssh/ssh_host_${keytype}_key.pub
    [ -r "$f" ] && hv_keys="$hv_keys$(cat "$f")"$'\n'
done
if [ -z "$hv_keys" ]; then
    echo "Error: no host keys readable in /etc/ssh on this host (run on the hypervisor)." >&2
    exit 1
fi
while read -r keytype keydata _; do
    [ -n "$keytype" ] && printf '%s %s %s\n' "$HYPERVISOR_IP" "$keytype" "$keydata" >> "$tmp"
done <<< "$hv_keys"
echo "pinned hypervisor ($HYPERVISOR_IP)"

install -m 0644 "$tmp" "$KNOWN_HOSTS"
echo "wrote $KNOWN_HOSTS"
